async function loadMetadataQuality(){const summary=$('#metadataQualitySummary'),list=$('#metadataQualityList');summary.innerHTML='<p class="review-empty">정보 완성도를 계산하고 있어요.</p>';list.innerHTML='';try{const r=await fetch('/api/metadata-quality'),data=await r.json();if(r.status===401||r.status===403)return;if(!r.ok)throw new Error(data.error||'품질 현황을 불러오지 못했습니다.');summary.innerHTML=`<strong>평균 ${esc(data.average)}%</strong><span>전체 ${esc(data.total)} · 보완 필요 ${esc(data.incomplete)} · 완료 ${esc(data.complete)}</span>`;metadataQualityItems=data.items||[];for(const item of metadataQualityItems)works[item.work.id]={...item.work,...works[item.work.id]};renderMetadataQuality()}catch(error){metadataQualityItems=[];summary.innerHTML=`<p class="review-empty">${esc(error.message)}</p>`}}
function metadataCandidateValue(item,field){return field==='year'?item.year:field==='creator'?item.creator:field==='poster'?item.posterUrl:field==='media_type'?item.mediaType:field==='intro'?item.description:item.source}
