function renderMetadataCandidates(){const {work,field,candidates}=metadataCandidateContext,label=metadataQualityLabels[field]||field;$('#metadataCandidateTitle').textContent=`${work.title} · ${label} 후보 비교`;$('#metadataCandidateCurrent').innerHTML=`<strong>현재 작품</strong><span>${esc(work.title)} · ${esc(work.mediaType||work.type||'OTHER')} · ${esc(work.year||'연도 없음')} · ${esc(work.creator||'창작자 없음')}</span>`;$('#metadataCandidateList').innerHTML=candidates.map((candidate,index)=>{const value=metadataCandidateValue(candidate,field),url=metadataCandidateUrl(candidate),poster=field==='poster'&&safeUrl(value),assessment=scoreMetadataCandidate(candidate,work),tier=assessment.score>=80?'high':assessment.score>=55?'medium':'low';return`<article class="metadata-candidate ${tier}"><header><div>${poster?`<img src="${esc(safeUrl(value))}" alt="" loading="lazy" />`:''}<span><strong>${esc(candidate.title||work.title)}</strong><small>${esc(candidate.source||'무료 데이터')} · ${esc(candidate.mediaType||'매체 미상')} · ${esc(candidate.year||'연도 미상')}</small></span></div><em>${assessment.score}점</em></header><p class="metadata-candidate-value"><b>${esc(label)}</b>${esc(value)}</p><div class="metadata-candidate-checks">${assessment.checks.map(([name,status,ok])=>`<span class="${ok?'match':'mismatch'}">${esc(name)} · ${esc(status)}</span>`).join('')}</div><footer>${url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer nofollow">원문 확인 ↗</a>`:'<small>직접 연결 가능한 원문 없음</small>'}<button type="button" data-candidate-use="${index}">이 후보로 제안</button></footer></article>`}).join('')}
