async function suggestMetadataRepair(button){const id=button.dataset.qualityId,field=button.dataset.qualitySuggest,w=works[id];if(!w)return;const original=button.textContent;button.disabled=true;button.textContent='후보 비교 중…';try{const searchJob=fetch(`/api/search?q=${encodeURIComponent(w.originalTitle||w.title||'')}`).then(async r=>{const data=await r.json();if(!r.ok)throw new Error('무료 데이터 검색에 연결하지 못했습니다.');return data.items||[]}),artworkJob=field==='poster'?fetch(`/api/artwork?${new URLSearchParams({title:w.title||'',originalTitle:w.originalTitle||'',creator:w.creator||'',mediaType:w.mediaType||w.type||'OTHER',externalId:w.externalId||''})}`).then(r=>r.json()).catch(()=>null):Promise.resolve(null),[items,artwork]=await Promise.all([searchJob,artworkJob]),mediaType=w.mediaType||w.type||'OTHER',candidates=[...items];if(artwork?.posterUrl)candidates.unshift({...w,mediaType,posterUrl:artwork.posterUrl,source:artwork.source||'공식 이미지 제공처'});for(const url of artwork?.alternatives||[])candidates.push({...w,mediaType,posterUrl:url,source:artwork.source||'공식 이미지 제공처'});const seen=new Set,ranked=candidates.filter(item=>{const value=metadataCandidateValue(item,field),key=`${item.source}|${value}`;if(value===null||value===undefined||String(value).trim()===''||seen.has(key))return false;seen.add(key);return true}).map(item=>({item,assessment:scoreMetadataCandidate(item,w)})).filter(({assessment})=>assessment.score>=28).sort((a,b)=>b.assessment.score-a.assessment.score).slice(0,6).map(({item})=>item);if(!ranked.length)throw new Error(`${metadataQualityLabels[field]||field}의 동일 작품 후보를 찾지 못했습니다.`);metadataCandidateContext={work:{...w,id},field,candidates:ranked};$('#metadataReviewDialog').close();renderMetadataCandidates();$('#metadataCandidateDialog').showModal()}catch(error){toast(error.message)}finally{button.disabled=false;button.textContent=original}}
