const metadataFieldLabels={poster_url:'포스터·표지',release_year:'발표 연도',creator:'창작자',title:'작품 제목',media_type:'매체 구분'};
function metadataCompleteness(w){const text=value=>String(value||'').trim(),creator=text(w.creator),media=text(w.type||w.mediaType).toUpperCase(),checks=[{label:'발표 연도',issue:'year',ok:/^(18|19|20|21)\d{2}$/.test(text(w.year))},{label:'창작자',issue:'creator',ok:Boolean(creator&&!['작자 미상','제작진 정보 없음','정보 없음'].includes(creator))},{label:'포스터·표지',issue:'poster',ok:Boolean(safeUrl(w.posterUrl)||w.poster)},{label:'작품 소개',issue:'other',ok:Boolean(text(w.quote||w.editorialIntro||w.aiComment||w.description).length>=12)},{label:'매체 구분',issue:'media_type',ok:Boolean(media&&media!=='OTHER')},{label:'정보 출처',issue:'other',ok:Boolean(text(w.source||w.artwork?.source)||(w.wikidata?.matched===true))}],missing=checks.filter(item=>!item.ok);return{score:Math.round((checks.length-missing.length)/checks.length*100),missing}}
function paintMetadataProvenance(w){const box=$('#metadataProvenance'),items=Array.isArray(w._metadataProvenance)?w._metadataProvenance:[],confidence=w._metadataConfidence,quality=metadataCompleteness(w);if(!box)return;const tierLabels={high:'높음',medium:'보통',basic:'기본'},score=Math.max(0,Math.min(100,Number(confidence?.score)||0)),missing=quality.missing.length?`<div class="metadata-missing">${quality.missing.map(item=>`<button type="button" data-metadata-missing="${esc(item.issue)}">＋ ${esc(item.label)} 보완</button>`).join('')}</div><small>비어 있거나 확인이 필요한 항목을 선택하면 수정 제안으로 이어집니다.</small>`:'<small class="metadata-complete">기본 작품 정보가 모두 채워졌습니다.</small>',verified=items.length?`<section class="metadata-verification"><header><strong>✓ 검증된 작품 정보</strong>${confidence?`<em class="${esc(confidence.tier)}">근거 신뢰도 ${esc(tierLabels[confidence.tier]||'기본')} · ${score}</em>`:''}</header>${confidence?`<i class="metadata-confidence"><b style="width:${score}%"></b></i>`:''}<div>${items.map(item=>{const label=metadataFieldLabels[item.field]||item.field,type=metadataEvidenceLabels[item.evidenceType]||'검증 자료',url=safeUrl(item.sourceUrl);return url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer nofollow" title="근거 신뢰도 ${esc(item.confidence||0)}">${esc(label)} · ${esc(type)} ↗</a>`:`<span title="근거 신뢰도 ${esc(item.confidence||0)}">${esc(label)} · ${esc(type)}</span>`}).join('')}</div><small>출처 권위와 원문 연결 여부를 기준으로 계산하며, 작품의 가치 평가는 아닙니다.</small></section>`:'<section class="metadata-verification empty"><small>공개 검수를 마친 근거 출처는 아직 없습니다.</small></section>';box.hidden=false;box.innerHTML=`<header class="metadata-quality-header"><strong>작품 정보 상태</strong><em>완성도 ${quality.score}%</em></header><i class="metadata-completeness"><b style="width:${quality.score}%"></b></i>${missing}${verified}`}
