const duplicateFieldLabels={title:'제목',original_title:'원제',creator:'창작자',release_year:'연도',media_type:'매체',poster_url:'이미지',description:'소개',source:'출처',canonical_key:'식별키'};
async function openDuplicatePreview(button){button.disabled=true;try{const r=await fetch(`/api/duplicate-preview?left=${encodeURIComponent(button.dataset.left)}&right=${encodeURIComponent(button.dataset.right)}`),data=await r.json();if(!r.ok)throw new Error(data.error||'병합 미리보기를 만들지 못했습니다.');const impact=data.impact;$('#duplicatePreviewTitle').textContent=`${data.left.title} ↔ ${data.right.title}`;$('#duplicatePreviewBody').innerHTML=`<div class="duplicate-primary-choice"><strong>대표 작품 선택</strong><label><input type="radio" name="duplicate-primary" value="left" data-work-id="${esc(data.left.id)}" checked/> ${esc(data.left.title)}</label><label><input type="radio" name="duplicate-primary" value="right" data-work-id="${esc(data.right.id)}"/> ${esc(data.right.title)}</label></div>${data.warnings.length?`<div class="duplicate-warnings">${data.warnings.map(value=>`<p>⚠ ${esc(value)}</p>`).join('')}</div>`:''}<div class="duplicate-impact"><span>성좌 ${impact.archives.left+impact.archives.right}</span><span>연결 ${impact.connections.left+impact.connections.right}</span><span>추천 반응 ${impact.feedback.left+impact.feedback.right}</span><span>검수 기록 ${impact.reports.left+impact.reports.right}</span></div><div class="duplicate-comparison">${data.comparison.map(row=>`<article class="${row.conflict?'conflict':''}" data-merge-field="${esc(row.field)}"><strong>${esc(duplicateFieldLabels[row.field]||row.field)}</strong><label><input type="radio" name="field-${esc(row.field)}" value="left" ${row.suggested!=='right'?'checked':''}/> ${esc(metadataValue(row.left))}</label><label><input type="radio" name="field-${esc(row.field)}" value="right" ${row.suggested==='right'?'checked':''}/> ${esc(metadataValue(row.right))}</label></article>`).join('')}</div><label class="duplicate-confirm"><input type="checkbox" data-duplicate-confirm/> 두 작품의 성좌·연결·반응·검수 기록이 대표 작품으로 합쳐지고 중복 작품이 삭제됨을 확인했습니다.</label><button type="button" class="analyze-save" data-duplicate-merge disabled>선택대로 병합하기</button>`;$('#duplicatePreviewDialog').showModal()}catch(error){toast(error.message)}finally{button.disabled=false}}
async function submitDuplicateMerge(button){const dialog=$('#duplicatePreviewDialog'),primary=dialog.querySelector('input[name="duplicate-primary"]:checked'),primarySide=primary?.value;if(!primary||!['left','right'].includes(primarySide))return toast('대표 작품을 선택해 주세요.');const other=dialog.querySelector(`input[name="duplicate-primary"]:not([value="${primarySide}"])`),fields={};dialog.querySelectorAll('[data-merge-field]').forEach(row=>{const selected=row.querySelector('input:checked');fields[row.dataset.mergeField]=selected?.value===primarySide?'target':'duplicate'});if(!confirm('중복 작품 카탈로그는 복구할 수 있지만 통합된 개인화 데이터는 자동으로 다시 나뉘지 않습니다. 선택한 내용대로 계속할까요?'))return;button.disabled=true;button.textContent='안전하게 병합하는 중…';try{const response=await fetch('/api/duplicate-merge',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({targetId:primary.dataset.workId,duplicateId:other?.dataset.workId,fields,confirmation:'MERGE_DUPLICATES'})}),data=await response.json();if(!response.ok)throw new Error(data.error||'병합하지 못했습니다.');dialog.close();await Promise.all([loadDuplicateCandidates(),loadDuplicateMergeHistory(),loadMetadataQuality(),loadMetadataReviewQueue(),loadMetadataChangeHistory()]);toast(`중복 작품을 병합했습니다. 감사 기록 #${data.auditId||'-'}`)}catch(error){toast(error.message);button.disabled=false;button.textContent='선택대로 병합하기'}}
async function restoreDuplicateMerge(id,encodedTitle,button){const title=decodeURIComponent(encodedTitle),reason=prompt(`「${title}」 카탈로그 복구 사유를 입력해 주세요.\n통합된 개인 성좌·반응 데이터는 안전을 위해 다시 분리하지 않습니다.`,'잘못 병합된 별개의 작품으로 확인');if(reason===null)return;if(reason.trim().length<5)return toast('복구 사유를 5자 이상 입력해 주세요.');if(!confirm('삭제됐던 작품 정보만 복구합니다. 개인화 데이터는 대표 작품에 유지됩니다. 계속할까요?'))return;button.disabled=true;button.textContent='복구 중…';try{const response=await fetch(`/api/duplicate-merges/${encodeURIComponent(id)}`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({confirmation:'RESTORE_CATALOG',reason:reason.trim()})}),data=await response.json();if(!response.ok)throw new Error(data.error||'복구하지 못했습니다.');await Promise.all([loadDuplicateCandidates(),loadDuplicateMergeHistory(),loadMetadataQuality()]);toast('삭제됐던 작품 카탈로그를 복구했습니다. 개인화 데이터는 대표 작품에 유지됩니다.')}catch(error){toast(error.message);button.disabled=false;button.textContent='작품 카탈로그 복구'}}
async function loadDuplicateMergeHistory(){const summary=$('#duplicateMergeSummary'),list=$('#duplicateMergeList');summary.innerHTML='<p class="review-empty">병합 무결성을 확인하고 있어요.</p>';list.innerHTML='';try{const response=await fetch('/api/duplicate-merges'),data=await response.json();if(response.status===401||response.status===403)return;if(!response.ok)throw new Error(data.error||'병합 이력을 불러오지 못했습니다.');summary.innerHTML=`<strong>${esc(data.count)}건 기록</strong><span>병합 유지 ${esc(data.active)}건 · 카탈로그 복구 ${esc(data.restored)}건 · 확인 필요 ${esc(data.needsAttention)}건</span>`;list.innerHTML=data.items.length?data.items.map(item=>{const impact=item.impact||{},integrity=item.integrity||{},restored=item.status==='restored',status=restored?'↺ 카탈로그 복구됨':integrity.healthy?'✓ 무결성 정상':'⚠ 확인 필요';return`<article class="metadata-review-item duplicate-merge-item ${integrity.healthy?'healthy':'attention'} ${restored?'restored':''}"><header><strong>${esc(item.targetTitle)}</strong><span>${status}</span></header><p>${restored?`<b>${esc(item.removedTitle)}</b> 카탈로그가 다시 독립됨`:`<s>${esc(item.removedTitle)}</s> → 대표 작품으로 통합`}</p><div class="duplicate-merge-impact"><span>성좌 ${esc(impact.archives||0)}</span><span>연결 ${esc(impact.connections||0)}</span><span>반응 ${esc(impact.feedback||0)}</span><span>검수 ${esc(impact.reports||0)}</span></div><dl><dt>대표 ID</dt><dd>${esc(item.targetId)}</dd><dt>${restored?'복구 ID':'제거 ID'}</dt><dd>${esc(item.removedId)}</dd></dl><p>${new Date(item.mergedAt).toLocaleString('ko-KR')} 병합 · 감사 기록 #${esc(item.id)}</p>${restored?`<p class="duplicate-restore-note">${new Date(item.restoredAt).toLocaleString('ko-KR')} 복구${item.restoreReason?` · ${esc(item.restoreReason)}`:''}<br>개인화 데이터는 대표 작품에 안전하게 유지됩니다.</p>`:item.recoverable?`<button class="duplicate-restore-button" type="button" onclick="restoreDuplicateMerge(${Number(item.id)},'${attr(item.removedTitle)}',this)">작품 카탈로그 복구</button>`:''}</article>`}).join(''):'<p class="review-empty">아직 실행된 중복 병합이 없습니다.</p>'}catch(error){summary.innerHTML=`<p class="review-empty">${esc(error.message)}</p>`}}
async function openMetadataReview(){await Promise.all([loadMetadataReviewQueue(),loadMetadataChangeHistory(),loadMetadataQuality(),loadDuplicateCandidates(),loadDuplicateMergeHistory()]);$('#metadataReviewDialog').showModal()}
async function searchMetadata(w){const queries=[w.originalTitle,w.title].filter((value,index,list)=>value&&list.indexOf(value)===index),responses=await Promise.allSettled(queries.map(query=>fetch(`/api/search?q=${encodeURIComponent(query)}`).then(async response=>{const data=await response.json();if(!response.ok)throw new Error('metadata');return data.items||[]}))),items=responses.flatMap(result=>result.status==='fulfilled'?result.value:[]);return bestMetadataMatch(items,w)}
async function resolveWorkMetadata(id,w){if(w.year||w._metadataResolving||w._metadataResolved)return;w._metadataResolving=true;try{const matched=await searchMetadata(w);works[id]=matched?{...w,...matched,id,title:w.title||matched.title,creator:w.creator&&w.creator!=='작자 미상'?w.creator:matched.creator,_metadataResolved:true,_metadataResolving:false}:{...w,_metadataResolved:true,_metadataResolving:false};if(current===id)renderWork()}catch{works[id]={...w,_metadataResolved:true,_metadataResolving:false};if(current===id)$('#workYear').textContent='연도 정보 확인 불가'}}
async function loadArtwork(id,w){if(w._artworkLoaded)return;if(artworkCache.has(id)){await artworkCache.get(id);return}const params=new URLSearchParams({title:w.title||'',creator:w.creator||'',mediaType:w.type||w.mediaType||'OTHER',externalId:w.externalId||''}),job=fetch(`/api/artwork?${params}`).then(async r=>{const data=await r.json();if(!r.ok)throw new Error(data.error||'artwork');works[id]._artworkLoaded=true;if(data.posterUrl){works[id].posterUrl=data.posterUrl;works[id].artwork={source:data.source,kind:data.kind,selection:data.selection,publisher:data.publisher||null,isbn:data.isbn||null,alternatives:data.alternatives||[]};if(current===id)paintPoster(works[id])}return data}).catch(()=>{works[id]._artworkLoaded=true;return null});artworkCache.set(id,job);await job}
function paintPoster(w){const p=$('#workPoster'),poster=safeUrl(w.posterUrl);p.className='poster '+(poster?'poster-live':(w.poster||'poster-live'));p.style.backgroundImage=poster?`linear-gradient(0deg,rgba(8,10,14,.36),rgba(8,10,14,.02)),url("${poster}")`:'';p.innerHTML=poster?`<span></span><i>${esc(w.year||'')}</i>`:`<span>${esc(w.posterText||w.title)}</span><i>${esc(w.year||'')}</i>`;p.title=w.artwork?.selection||'';p.setAttribute('aria-label',poster?`${w.title} 대표 이미지. ${w.artwork?.selection||'공식 데이터 제공처 이미지'}`:`${w.title} 이미지 준비 중`)}
function renderWork(){const w=works[current];paintPoster(w);$('#workType').textContent=w.type||w.mediaType;$('#workYear').textContent=w.year||'연도 확인 중';const bridge=paintBridgeContext(w);paintPublishers(w);paintMetadataProvenance(w);$('.award').textContent=bridge.awards.length?`🏆 ${bridge.awards.join(' · ')}`:w.source||'';$('#workTitle').textContent=w.title;$('#workCreator').textContent=w.creator;const intro=w.quote||w.editorialIntro||w.aiComment||((w.description||'작품 설명이 아직 없습니다.').slice(0,180));$('#workQuote').textContent=`“${intro.replace(/^[“\"]|[”\"]$/g,'')}”`;const dna=w.analysis?.tags?.map(t=>t.tag)||w.tags||[];$('#tasteTags').innerHTML=(dna.length?dna:['Taste DNA 분석 전']).map(t=>`<span class="tag">#${esc(t)}</span>`).join('');$('#saveBtn').classList.toggle('saved',archive.includes(current));$('#saveBtn').innerHTML=archive.includes(current)?'<span>✓</span> 내 성좌에서 빼기':'<span>＋</span> 내 성좌에 담기';renderRecs();loadArtwork(current,w);loadCulturalContext(current,w);loadBookPublishers(current,w);loadMetadataProvenance(current,w);loadEditorialIntro(current,w);resolveWorkMetadata(current,w)}
async function batchMetadataRepair(){const button=$('#metadataQualityBatch'),selected=metadataQualityItems.filter(item=>metadataQualitySelected.has(item.work.id)).slice(0,10);if(!selected.length)return;if(!confirm(`선택한 ${selected.length}개 작품의 누락 정보를 조사해 검수 대기에 등록할까요? 작품 정보는 자동 변경되지 않습니다.`))return;button.disabled=true;button.textContent='무료 데이터 조사 중…';let submitted=0,skipped=0;try{for(const entry of selected){const w=entry.work,r=await fetch(`/api/search?q=${encodeURIComponent(w.originalTitle||w.title||'')}`),data=await r.json();if(!r.ok){skipped++;continue}const best=(data.items||[]).map(item=>({item,assessment:scoreMetadataCandidate(item,w)})).sort((a,b)=>b.assessment.score-a.assessment.score)[0];if(!best||best.assessment.score<55){skipped++;continue}let usedOther=false;for(const field of entry.missing){if(submitted>=20)break;const issue={year:'year',creator:'creator',poster:'poster',media_type:'media_type',intro:'other',source:'other'}[field]||'other';if(issue==='other'&&usedOther)continue;const value=metadataCandidateValue(best.item,field);if(value===null||value===undefined||String(value).trim()==='')continue;if(issue==='other')usedOther=true;const response=await fetch('/api/metadata-reports',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({work:{...w,id:w.id},issueType:issue,suggestedValue:String(value),evidenceType:'authority_database',sourceUrl:metadataCandidateUrl(best.item),note:`${best.item.source||'무료 메타데이터'} 일괄 보강 후보 · 작품 일치 참고 점수 ${best.assessment.score}점. 원문 확인 후 승인해 주세요.`})});if(response.ok)submitted++;else skipped++}}metadataQualitySelected.clear();renderMetadataQuality();await loadMetadataReviewQueue();toast(`${submitted}건을 검수 대기에 등록했어요.${skipped?` ${skipped}건은 근거 부족으로 건너뛰었습니다.`:''}`)}catch{toast('일괄 보강 중 일부 데이터를 불러오지 못했습니다.')}finally{button.textContent='선택 작품 일괄 보강';paintMetadataQualitySelection()}}
function hydrateRecommendationArtwork(){}
async function renderRecs(){
  const labels={story:'서사의 뼈대를 따라 연결했어요.',mood:'보고 난 뒤 남는 감정의 온도를 따라갑니다.',idea:'작품이 던지는 질문을 다음 매체로 이어갑니다.',visual:'색, 공간, 이미지의 리듬으로 연결했어요.',deep:'장르는 멀지만 취향의 핵심이 맞닿은 작품들입니다.'},box=$('#recommendations');
  $('#connectionIntro').textContent=labels[mode];
  if(recommendationController)recommendationController.abort();
  const selected=current,selectedMode=mode,key=`${current}:${mode}`;
  if(recs[current]){
    const list=recs[current]?.[mode]||recs[current]?.deep;
    box.innerHTML=list.map(r=>`<article class="rec-card" role="button" tabindex="0" aria-label="${esc(r[1])} 작품 정보 열기" data-art-title="${esc(r[1])}" data-art-creator="${esc(r[2])}" data-art-type="${esc(r[0])}" data-art-original="${esc(r[4]||'')}" data-art-id="${esc(r[5]||'')}"><span class="rec-art" role="img" aria-label="${esc(r[1])} 공식 이미지" hidden></span><span class="type">${esc(r[0])}</span><span class="arrow">↗</span><h4>${esc(r[1])}</h4><span class="creator">${esc(r[2])}</span><p class="reason">“${esc(r[3])}”</p></article>`).join('');
    hydrateRecommendationArtwork();return;
  }
  const cached=recommendationCache.get(key);if(cached?.length){paintRecommendations(cached);return}
  recommendationController=new AbortController();box.setAttribute('aria-busy','true');box.innerHTML='<div class="recommendation-loading">Taste DNA로 다른 매체를 탐색하고 있어요…</div>';
  try{const r=await fetch('/api/recommendations',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({work:{...works[current],id:current},mode}),signal:recommendationController.signal}),data=await r.json();if(!r.ok)throw new Error(data.error||'recommendations');if(selected!==current||selectedMode!==mode)return;const items=data.items||[];if(items.length)recommendationCache.set(key,items);else recommendationCache.delete(key);const persisted=items.filter(item=>item.persisted);connectionGraph=[...persisted,...connectionGraph.filter(x=>!persisted.some(y=>y.fromWorkId===x.fromWorkId&&y.id===x.id&&String(y.mode).split(':')[0]===String(x.mode).split(':')[0]))];paintRecommendations(items)}catch(error){if(error.name==='AbortError')return;box.innerHTML=`<div class="recommendation-loading">${error.message==='로그인이 필요합니다.'?'로그인하면 Taste DNA 추천을 사용할 수 있습니다.':'지금은 연결 작품을 찾지 못했습니다. 잠시 후 다시 시도해 주세요.'}</div>`}finally{box.setAttribute('aria-busy','false')}
}
function paintRecommendations(items){items.forEach(w=>works[w.id]={...w,...works[w.id]});$('#recommendations').innerHTML=items.length?items.map(w=>{const fallback=String(w.description||'').split(/[.!?。]\s*/)[0].slice(0,120)||'작품의 핵심을 읽고 있습니다.';return`<article class="rec-card rec-action" data-card-id="${esc(w.id)}" data-art-title="${esc(w.title)}" data-art-creator="${esc(w.creator)}" data-art-type="${esc(w.mediaType)}" data-art-url="${esc(w.posterUrl||'')}" data-art-original="${esc(w.originalTitle||'')}" data-art-id="${esc(w.externalId||'')}"><span class="rec-art" role="img" aria-label="${esc(w.title)} 공식 이미지" hidden></span><button class="rec-open" data-recommendation="${esc(w.id)}"><span class="type">${esc(w.mediaType)}</span><span class="match-score">${Math.round((w.similarity||0)*100)}% DNA</span><h4>${esc(w.title)}</h4><span class="creator">${esc(w.creator)}</span><p class="reason" data-editorial-id="${esc(w.id)}">“${esc(w.editorialIntro||fallback)}”</p><small>${(w.sharedTags||[]).map(t=>`#${esc(t)}`).join(' ')}${w.persisted?' · 성좌에 기록됨':' · 무료 메타데이터 연결'}</small></button><div class="rec-feedback" aria-label="이 추천이 마음에 드나요?"><span>이 연결은 어때요?</span><button data-feedback="1" data-from="${esc(w.fromWorkId||current)}" data-to="${esc(w.id)}" data-mode="${esc(w.mode||mode)}" data-shared="${esc(JSON.stringify(w.sharedTags||[]))}" class="${w.feedback===1?'selected':''}" aria-label="좋은 추천">♥</button><button data-feedback="-1" data-from="${esc(w.fromWorkId||current)}" data-to="${esc(w.id)}" data-mode="${esc(w.mode||mode)}" data-shared="${esc(JSON.stringify(w.sharedTags||[]))}" aria-label="관심 없는 추천">숨기기</button></div></article>`}).join(''):'<div class="recommendation-loading">이 모드에서 충분히 닮은 작품을 찾지 못했습니다.</div>';hydrateRecommendationArtwork();hydrateRecommendationIntros(items)}
async function hydrateRecommendationIntros(items){await Promise.all(items.map(async w=>{await loadEditorialIntro(w.id,works[w.id]);const text=works[w.id]?.editorialIntro;if(!text)return;const line=[...document.querySelectorAll('[data-editorial-id]')].find(element=>element.dataset.editorialId===w.id);if(line)line.textContent=`“${text}”`}))}
async function sendRecommendationFeedback(button){const value=Number(button.dataset.feedback),card=button.closest('.rec-card');let sharedTags=[];try{sharedTags=JSON.parse(button.dataset.shared||'[]')}catch{}button.disabled=true;try{const r=await fetch('/api/recommendation-feedback',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({fromWorkId:button.dataset.from,toWorkId:button.dataset.to,mode:button.dataset.mode,value,sharedTags})}),data=await r.json();if(!r.ok)throw new Error(data.error||'feedback');if(value===-1){card.remove();for(const [key,items] of recommendationCache){const next=items.filter(item=>item.id!==button.dataset.to);if(next.length)recommendationCache.set(key,next);else recommendationCache.delete(key)}if(!$('#recommendations').children.length)$('#recommendations').innerHTML='<div class="recommendation-loading">이 추천은 숨겼어요. 탭을 다시 누르면 새로운 연결을 찾습니다.</div>';toast('이 작품은 다음 추천에서 제외할게요.')}else{button.classList.add('selected');toast(data.learnedTags?'이 취향의 결을 다음 추천에 반영할게요.':'좋은 연결로 기억했어요.')}}catch(error){button.disabled=false;toast(error.message||'반응을 저장하지 못했습니다.')}}
async function openStaticRecommendation(card){if(card.dataset.opening==='true')return;card.dataset.opening='true';card.setAttribute('aria-busy','true');const title=card.dataset.artTitle||'',creator=card.dataset.artCreator||'작자 미상',mediaType=card.dataset.artType||'OTHER',originalTitle=card.dataset.artOriginal||'';try{const matched=await searchMetadata({title,originalTitle,creator,mediaType});if(matched){works[matched.id]={...matched,...works[matched.id]};selectWork(matched.id);return}const id=`static:${mediaType.toLowerCase()}:${encodeURIComponent(title)}`;works[id]={id,title,originalTitle,creator,type:mediaType,mediaType,year:null,source:'Connection Mode',tags:[]};selectWork(id)}catch{const id=`static:${mediaType.toLowerCase()}:${encodeURIComponent(title)}`;works[id]={id,title,originalTitle,creator,type:mediaType,mediaType,year:null,source:'Connection Mode',tags:[]};selectWork(id);toast('기본 작품 정보를 먼저 열었어요. 세부 정보는 연결되는 대로 채워집니다.')}finally{card.dataset.opening='false';card.removeAttribute('aria-busy')}}
function selectWork(id){current=id;mode='deep';$$('#modeTabs button').forEach(b=>b.classList.toggle('active',b.dataset.mode==='deep'));renderWork();$('#searchResults').hidden=true;$('#searchInput').value='';$('#workSection').scrollIntoView({behavior:'smooth',block:'start'})}
function toast(msg){const t=$('#toast');clearTimeout(toastTimer);t.textContent=msg;t.classList.add('show');toastTimer=setTimeout(()=>t.classList.remove('show'),2200)}
function paintPreferenceSignals(){const box=$('#preferenceSignals');if(!box)return;const tags=tasteProfile.learnedTags||[];box.innerHTML=tags.length?`<div class="preference-title"><span>추천에서 학습한 취향</span><small>${Number(tasteProfile.feedbackCount)||0}개의 반응</small></div><div class="preference-tags">${tags.map(item=>`<span class="${item.sentiment==='more'?'more':'less'}">${item.sentiment==='more'?'＋':'−'} #${esc(item.tag)}</span>`).join('')}</div>`:'<p>추천에 반응하면 개인화된 취향 신호가 여기에 쌓입니다.</p>'}
function paintBridgeWork(){const box=$('#bridgeWork');if(!box)return;const items=archive.filter(id=>works[id]);if(!items.length){box.innerHTML='<p>작품을 저장하면 성좌의 핵심 다리를 분석합니다.</p>';return}const ranked=items.map(id=>{const graphLinks=connectionGraph.filter(edge=>edge.fromWorkId===id||edge.id===id).length,vectorLinks=similarityEdges.filter(edge=>edge.sourceId===id||edge.targetId===id).length,profile=bridgeProfile(works[id]);return{id,profile,links:graphLinks+vectorLinks,total:profile.score+(graphLinks+vectorLinks)*4}}).sort((a,b)=>b.total-a.total),best=ranked[0],w=works[best.id];box.innerHTML=`<div class="bridge-work-title"><span>성좌의 핵심 다리</span><strong>${best.profile.score}</strong></div><h4>${esc(w.title)}</h4><p>${esc(best.profile.context)}</p><small>${best.links}개의 성좌 연결 · ${best.profile.awards.length?best.profile.awards.map(esc).join(' · '):'메타데이터 기반 분석'}</small>`}
async function loadTasteProfile(){try{const r=await fetch('/api/taste-profile'),data=await r.json();if(r.ok){tasteProfile=data;$('#tasteStatement').textContent=data.statement;paintPreferenceSignals()}}catch{}}
async function loadSimilarities(){try{const r=await fetch('/api/taste-similarities'),data=await r.json();similarityEdges=r.ok?data.edges||[]:[]}catch{similarityEdges=[]}}
async function loadConnections(){try{const r=await fetch('/api/connections'),data=await r.json();connectionGraph=r.ok?data.items||[]:[];connectionGraph.forEach(w=>works[w.id]={...w,...works[w.id]})}catch{connectionGraph=[]}}
async function loadConstellationGraph(){try{const r=await fetch('/api/constellation'),data=await r.json();if(!r.ok)throw new Error(data.error||'constellation');constellationGraph=data;(data.nodes||[]).forEach(w=>works[w.id]={...w,...works[w.id]});similarityEdges=(data.edges||[]).map(edge=>({sourceId:edge.sourceId,targetId:edge.targetId,similarity:edge.score}));return data}catch{constellationGraph=null;return null}}
async function loadArchive(){archiveError='';try{const r=await fetch('/api/archive');const data=await r.json();if(!r.ok)throw new Error(data.error||'archive');archive=data.items.map(w=>w.id);data.items.forEach(w=>works[w.id]=w);archiveReady=true;archiveError='';$('#archiveCount').textContent=archive.length;renderWork();if(!$('#archiveView').hidden){renderArchive();paintBridgeWork();renderTasteReport();renderArchiveManager()}await Promise.allSettled([loadTasteProfile(),loadSimilarities(),loadConnections(),loadConstellationGraph()]);if(!$('#archiveView').hidden){renderArchive();paintBridgeWork();renderTasteReport();renderArchiveManager()}}catch(error){archiveReady=false;archiveError=error.message||'archive';$('#archiveCount').textContent='!';if(!$('#archiveView').hidden)$('#constellation').innerHTML='<div class="archive-empty">아카이브를 불러오지 못했습니다.<br><button class="archive-retry" data-retry-archive>다시 불러오기</button></div>';toast(error.message==='로그인이 필요합니다.'?'로그인 후 아카이브를 사용할 수 있어요.':'아카이브 연결을 확인해 주세요.')}}
async function save(){if(!archiveReady){toast(archiveError==='로그인이 필요합니다.'?'로그인 후 아카이브를 사용할 수 있어요.':archiveError?'아카이브 연결을 확인한 뒤 다시 시도해 주세요.':'아카이브를 불러오는 중입니다.');return}if(!archive.includes(current)){selectedRating=5;$('#commentInput').value='';paintRating();$('#saveDialogTitle').textContent=`${works[current].title}이 왜 좋았나요?`;$('#saveDialog').showModal();return}await deleteArchiveItem(current)}
async function submitSave(){const button=$('#analyzeSaveBtn');button.disabled=true;button.textContent='Taste DNA를 읽는 중…';try{const r=await fetch('/api/archive',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({work:{...works[current],id:current},rating:selectedRating,myComment:$('#commentInput').value})}),data=await r.json();if(!r.ok)throw new Error(data.error||'save');works[current]=data.work;archive=[current,...archive.filter(id=>id!==current)];archiveReady=true;archiveError='';$('#archiveCount').textContent=archive.length;await Promise.all([loadTasteProfile(),loadSimilarities(),loadConstellationGraph()]);$('#saveDialog').close();renderWork();toast('Taste DNA가 성좌에 기록됐어요.')}catch(error){toast(error.message||'분석하지 못했습니다.')}finally{button.disabled=false;button.textContent='저장하고 Taste DNA 만들기'}}
function paintRating(){$$('#ratingInput button').forEach(b=>b.classList.toggle('lit',Number(b.dataset.rating)<=selectedRating))}
function showView(view){$('#discoverView').hidden=view!=='discover';$('#archiveView').hidden=view!=='archive';$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='archive'){if(!archiveReady&&archiveError)loadArchive();else{renderArchive();paintBridgeWork();renderTasteReport();renderArchiveManager()}}scrollTo({top:0,behavior:'smooth'})}
function constellationLayout(nodes,edges){if(nodes.length===1)return new Map([[nodes[0].id,[50,50]]]);const states=new Map(nodes.map((node,index)=>{const angle=-Math.PI/2+index*(Math.PI*2/nodes.length),radius=nodes.length<5?28:34;return[node.id,{x:50+Math.cos(angle)*radius,y:50+Math.sin(angle)*radius,vx:0,vy:0}]}));for(let step=0;step<64;step++){const list=[...states.entries()];for(let i=0;i<list.length;i++)for(let j=i+1;j<list.length;j++){const a=list[i][1],b=list[j][1],dx=a.x-b.x,dy=a.y-b.y,d2=Math.max(9,dx*dx+dy*dy),force=20/d2;a.vx+=dx*force;a.vy+=dy*force;b.vx-=dx*force;b.vy-=dy*force}for(const edge of edges){const a=states.get(edge.sourceId),b=states.get(edge.targetId);if(!a||!b)continue;const dx=b.x-a.x,dy=b.y-a.y,d=Math.max(1,Math.hypot(dx,dy)),target=18+(1-(Number(edge.score)||0))*28,force=(d-target)*(.004+(Number(edge.score)||0)*.006);a.vx+=dx/d*force;a.vy+=dy/d*force;b.vx-=dx/d*force;b.vy-=dy/d*force}for(const state of states.values()){state.vx+=(50-state.x)*.004;state.vy+=(50-state.y)*.004;state.vx*=.78;state.vy*=.78;state.x=Math.max(10,Math.min(90,state.x+state.vx));state.y=Math.max(13,Math.min(87,state.y+state.vy))}}return new Map([...states].map(([id,state])=>[id,[state.x,state.y]]))}
function showConstellationNode(id){const w=works[id];if(!w)return;const node=(constellationGraph?.nodes||[]).find(item=>item.id===id),tags=w.analysis?.tags?.slice(0,4).map(t=>t.tag).join(' / ')||'Taste DNA 분석 전',links=(constellationGraph?.edges||[]).filter(edge=>edge.sourceId===id||edge.targetId===id),strongest=[...links].sort((a,b)=>b.score-a.score)[0],other=strongest&&(strongest.sourceId===id?strongest.targetId:strongest.sourceId),match=other&&works[other]?`<div class="vector-match">↔ ${esc(works[other].title)} · ${Math.round(strongest.score*100)}% 연결</div>`:'';$('#connectionDetail').innerHTML=`<strong>${esc(w.title)}</strong> — ${esc(tags)}${match}<div class="archive-review"><strong>${'★'.repeat(Math.max(0,Math.min(5,Number(w.rating)||0)))}</strong> ${esc(w.myComment||w.aiComment||'')}</div><small class="node-meta">${links.length}개 연결 · 성좌 중심도 ${Math.round((node?.centrality||0)*100)}</small>`}
function showConstellationEdge(index){const edge=(constellationGraph?.edges||[])[index];if(!edge)return;const from=works[edge.sourceId],to=works[edge.targetId];if(!from||!to)return;$('#connectionDetail').innerHTML=`<div class="edge-detail-head"><strong>${esc(from.title)}</strong><span>↔</span><strong>${esc(to.title)}</strong><em>${Math.round(edge.score*100)}%</em></div><p>${esc(edge.reason||'Taste DNA가 닮은 작품입니다.')}</p><div class="edge-tags">${(edge.sharedTags||[]).map(tag=>`<span>#${esc(tag)}</span>`).join('')}</div><small>${edge.discovery?'추천에서 발견한 경로 · ':''}${esc((edge.mode||edge.type||'taste').toUpperCase())}</small>`}
function renderArchive(){if(!archiveReady){$('#constellation').innerHTML=archiveError?`<p class="archive-empty">${archiveError==='로그인이 필요합니다.'?'로그인 후 아카이브를 사용할 수 있어요.':'아카이브를 불러오지 못했습니다. 잠시 후 다시 시도해 주세요.'}</p>`:'<p class="archive-empty">아카이브를 불러오고 있어요…</p>';return}const fallbackNodes=archive.filter(id=>works[id]).map(id=>({id,...works[id],centrality:0,cluster:0})),nodes=(constellationGraph?.nodes||fallbackNodes).filter(node=>archive.includes(node.id)&&works[node.id]),items=nodes.map(node=>node.id);if(!items.length){$('#constellation').innerHTML='<p class="archive-empty">아직 저장한 작품이 없습니다.<br>탐색에서 첫 작품을 성좌에 담아보세요.</p>';$('#connectionDetail').textContent='작품이 쌓이면 서로 닮은 이유를 연결해 드립니다.';$('#dnaBars').innerHTML='<p class="archive-empty">첫 작품을 저장하면 Taste DNA가 생성됩니다.</p>';return}let edges=(constellationGraph?.edges||similarityEdges.map((edge,index)=>({id:`legacy:${index}`,sourceId:edge.sourceId,targetId:edge.targetId,type:'taste',score:edge.similarity,reason:'Taste DNA가 닮은 작품입니다.',sharedTags:[]}))).filter(edge=>items.includes(edge.sourceId)&&items.includes(edge.targetId));if(graphFilter==='taste')edges=edges.filter(edge=>edge.type==='taste');if(graphFilter==='discovery')edges=edges.filter(edge=>edge.discovery||edge.type==='discovery');const positions=constellationLayout(nodes,edges),positionById=new Map(items.map(id=>[id,positions.get(id)||[50,50]]));let lines=edges.map(edge=>{const a=positionById.get(edge.sourceId),b=positionById.get(edge.targetId),s=Math.max(0,Math.min(1,Number(edge.score)||0)),index=(constellationGraph?.edges||[]).indexOf(edge),kind=edge.discovery?'discovery':'taste';return`<line class="constellation-edge ${kind}" data-edge-index="${index}" x1="${a[0]}%" y1="${a[1]}%" x2="${b[0]}%" y2="${b[1]}%" stroke-opacity="${(.22+s*.72).toFixed(2)}" stroke-width="${(1+s*2.4).toFixed(2)}"/>`}).join('');if(!lines)for(let i=1;i<items.length;i++){const a=positionById.get(items[0]),b=positionById.get(items[i]);lines+=`<line class="constellation-edge pending" x1="${a[0]}%" y1="${a[1]}%" x2="${b[0]}%" y2="${b[1]}%"/>`}const bridge=constellationGraph?.bridge,$map=$('#constellation');$map.innerHTML=`<svg aria-label="작품 사이 연결선">${lines}</svg>`+nodes.map(node=>{const p=positionById.get(node.id),type=String(works[node.id].type||works[node.id].mediaType||'OTHER').toLowerCase(),size=Math.min(1.45,1+Number(node.centrality||0)*.08);return`<button class="star-node ${esc(type)} ${node.id===bridge?'bridge':''}" style="left:${p[0]}%;top:${p[1]}%;--node-scale:${size}" data-node="${esc(node.id)}"><i></i><span>${esc(works[node.id].title)}</span></button>`}).join('');$map.onclick=event=>{const node=event.target.closest('[data-node]');if(node){showConstellationNode(node.dataset.node);return}const edge=event.target.closest('[data-edge-index]');if(edge)showConstellationEdge(Number(edge.dataset.edgeIndex))};const stats=constellationGraph?.stats;$('#constellationStats').textContent=stats?`${stats.works}개 작품 · ${stats.connections}개 연결 · ${stats.clusters}개 취향 군집`:`${items.length}개 작품 · 연결 분석 중`;const dna=tasteProfile.tags||[];$('#dnaBars').innerHTML=dna.length?dna.map(d=>`<div class="dna-row"><div class="dna-label"><span>${esc(d.tag)}</span><span>${Number(d.score)||0}</span></div><div class="dna-track"><i style="width:${Math.max(0,Math.min(100,Number(d.score)||0))}%"></i></div></div>`).join('')+`<small class="dna-engine">Taste DNA · ${edges.length}개의 현재 표시 연결 · ${connectionGraph.length}개의 발견 연결</small>`:'<p class="archive-empty">저장한 작품을 분석하고 있어요.</p>'}

function tasteReportData(){const nodes=(constellationGraph?.nodes||archive.map(id=>works[id]).filter(Boolean)),edges=constellationGraph?.edges||[],media=new Map;for(const work of nodes){const type=String(work.mediaType||work.type||'OTHER').toUpperCase();media.set(type,(media.get(type)||0)+1)}const mediaItems=[...media.entries()].sort((a,b)=>b[1]-a[1]),topTags=(tasteProfile.tags||[]).slice(0,5),bridge=works[constellationGraph?.bridge]||nodes[0],strongest=[...edges].sort((a,b)=>Number(b.score)-Number(a.score))[0],from=strongest&&works[strongest.sourceId],to=strongest&&works[strongest.targetId],statement=tasteProfile.statement||'작품을 더 저장하면 취향을 설명하는 문장이 만들어집니다.',text=[`나의 취향 성좌 · ${nodes.length}개 작품`,statement,topTags.length?`핵심 취향: ${topTags.map(item=>`#${item.tag}`).join(' ')}`:'',bridge?`핵심 다리 작품: ${bridge.title}`:'',from&&to?`가장 강한 연결: ${from.title} ↔ ${to.title} (${Math.round(Number(strongest.score)*100)}%)`:'','취향 성좌에서 만들었습니다.'].filter(Boolean).join('\n');return{nodes,edges,mediaItems,topTags,bridge,strongest,from,to,statement,text}}
function renderTasteReport(){const box=$('#tasteReportBody');if(!box)return;const report=tasteReportData();$('#shareTasteReport').disabled=!report.nodes.length;if(!report.nodes.length){box.innerHTML='<p class="report-empty">작품을 저장하면 취향 리포트가 만들어집니다.</p>';return}const maxMedia=Math.max(1,...report.mediaItems.map(([,count])=>count)),connection=report.from&&report.to?`<div class="report-block report-connection"><span>가장 강한 연결</span><strong>${esc(report.from.title)} <i>↔</i> ${esc(report.to.title)}</strong><small>${Math.round(Number(report.strongest.score)*100)}% · ${esc(report.strongest.reason||'Taste DNA가 닮은 작품')}</small></div>`:`<div class="report-block report-connection"><span>가장 강한 연결</span><strong>두 번째 작품을 기다리고 있어요</strong><small>작품이 둘 이상이면 연결의 강도를 분석합니다.</small></div>`;box.innerHTML=`<blockquote>${esc(report.statement)}</blockquote><div class="report-grid"><div class="report-block"><span>매체 구성</span><div class="media-mix">${report.mediaItems.map(([type,count])=>`<div><b>${esc(type)}</b><i><em style="width:${count/maxMedia*100}%"></em></i><small>${count}</small></div>`).join('')}</div></div><div class="report-block"><span>핵심 취향</span><div class="report-tags">${report.topTags.map(item=>`<b>#${esc(item.tag)} <small>${Math.round(Number(item.score)||0)}</small></b>`).join('')||'<small>분석 중</small>'}</div></div><div class="report-block"><span>핵심 다리 작품</span><strong>${esc(report.bridge?.title||'분석 중')}</strong><small>${report.bridge?`${Math.round(Number(report.bridge.centrality||0)*100)} 중심도 · ${report.edges.filter(edge=>edge.sourceId===report.bridge.id||edge.targetId===report.bridge.id).length}개 연결`:''}</small></div>${connection}</div>`}
async function shareTasteReport(){const report=tasteReportData();if(!report.nodes.length)return;try{if(navigator.share){await navigator.share({title:'나의 취향 성좌',text:report.text,url:location.origin});return}await navigator.clipboard.writeText(`${report.text}\n${location.origin}`);toast('개인 감상을 제외한 취향 요약을 복사했어요.')}catch(error){if(error.name!=='AbortError')toast('취향 요약을 공유하지 못했습니다.')}}
const portableWork=work=>({id:work.id,externalId:work.externalId||null,title:work.title,originalTitle:work.originalTitle||null,creator:work.creator||'작자 미상',year:work.year||null,mediaType:work.mediaType||work.type||'OTHER',posterUrl:safeUrl(work.posterUrl)||null,description:String(work.description||'').slice(0,4000),tags:Array.isArray(work.tags)?work.tags.slice(0,20).map(String):[],publishers:Array.isArray(work.publishers)?work.publishers.slice(0,20):[],editionVerified:Boolean(work.editionVerified),editorialIntro:work.editorialIntro||null,source:work.source||'Taste Constellation',wikidata:work.wikidata||null});
function archiveBackup(){return{format:'taste-constellation-archive',version:1,exportedAt:new Date().toISOString(),items:archive.map(id=>works[id]).filter(Boolean).map(work=>({work:portableWork(work),rating:Math.max(1,Math.min(5,Number(work.rating)||5)),myComment:String(work.myComment||'').slice(0,500),archiveState:work.archiveState==='planned'?'planned':'completed',savedAt:work.savedAt||null}))}}
function downloadArchiveFile(name,type,content){const url=URL.createObjectURL(new Blob([content],{type})),link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportArchiveJson(){if(!archiveReady||!archive.length){toast('내보낼 저장 작품이 없습니다.');return}const date=new Date().toISOString().slice(0,10);downloadArchiveFile(`taste-constellation-${date}.json`,'application/json;charset=utf-8',JSON.stringify(archiveBackup(),null,2));toast(`${archive.length}개 작품을 JSON으로 백업했어요.`)}
function csvCell(value){let text=String(value??'').replace(/"/g,'""');if(/^[=+\-@]/.test(text))text=`'${text}`;return`"${text}"`}
function exportArchiveCsv(){if(!archiveReady||!archive.length){toast('내보낼 저장 작품이 없습니다.');return}const rows=[['제목','원제','창작자','연도','매체','감상 상태','별점','한줄평','Taste DNA','저장일'],...archive.map(id=>works[id]).filter(Boolean).map(work=>[work.title,work.originalTitle||'',work.creator||'',work.year||'',work.mediaType||work.type||'OTHER',work.archiveState==='planned'?'보고 싶음':'감상 완료',work.archiveState==='planned'?'':work.rating||'',work.myComment||'',(work.analysis?.tags||[]).map(item=>item.tag).join(' · '),work.savedAt||''])],csv='\ufeff'+rows.map(row=>row.map(csvCell).join(',')).join('\r\n'),date=new Date().toISOString().slice(0,10);downloadArchiveFile(`taste-constellation-${date}.csv`,'text/csv;charset=utf-8',csv);toast(`${rows.length-1}개 작품을 CSV로 내보냈어요.`)}
function validateArchiveBackup(data){if(!data||data.format!=='taste-constellation-archive'||data.version!==1||!Array.isArray(data.items))throw new Error('취향 성좌 JSON 백업 파일이 아닙니다.');if(data.items.length>200)throw new Error('한 번에 최대 200개 작품까지 가져올 수 있습니다.');const seen=new Set,items=[];for(const entry of data.items){const work=entry?.work,id=String(work?.id||'').trim(),title=String(work?.title||'').trim();if(!id||!title||seen.has(id))continue;seen.add(id);items.push({work:portableWork({...work,id,title}),rating:Math.max(1,Math.min(5,Math.round(Number(entry.rating)||5))),myComment:String(entry.myComment||'').slice(0,500),archiveState:entry.archiveState==='planned'?'planned':'completed'})}if(!items.length)throw new Error('가져올 수 있는 작품이 없습니다.');return items}
async function importArchiveJson(file){const input=$('#importArchiveFile'),button=$('#importArchiveButton');try{if(!file)return;if(file.size>2_000_000)throw new Error('백업 파일은 2MB 이하여야 합니다.');const items=validateArchiveBackup(JSON.parse(await file.text())),existing=items.filter(item=>archive.includes(item.work.id)).length;if(!confirm(`${items.length}개 작품을 가져옵니다.${existing?`\n기존 ${existing}개 작품은 백업 내용으로 갱신됩니다.`:''}`))return;button.disabled=true;button.textContent='가져오는 중…';let cursor=0,saved=0,failed=0;async function worker(){while(cursor<items.length){const item=items[cursor++];try{const response=await fetch('/api/archive',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(item)}),data=await response.json();if(!response.ok)throw new Error(data.error||'import');saved++}catch{failed++}}}await Promise.all(Array.from({length:Math.min(4,items.length)},worker));await loadArchive();toast(failed?`${saved}개 복원, ${failed}개는 가져오지 못했습니다.`:`${saved}개 작품을 아카이브에 복원했어요.`)}catch(error){toast(error instanceof SyntaxError?'JSON 파일 형식이 올바르지 않습니다.':error.message||'백업을 가져오지 못했습니다.')}finally{input.value='';button.disabled=false;button.textContent='JSON 가져오기'}}
function archiveBridgeScore(workOrId){const work=typeof workOrId==='object'&&workOrId?workOrId:works[workOrId];return work?bridgeProfile(work).score:0}
function renderArchiveManager(){const box=$('#archiveLibrary');if(!box)return;const query=titleKey(archiveQuery),items=archive.map(id=>works[id]).filter(Boolean).filter(work=>archiveType==='all'||String(work.mediaType||work.type).toUpperCase()===archiveType).filter(work=>archiveState==='all'||(work.archiveState||'completed')===archiveState).filter(work=>!query||titleKey([work.title,work.creator,...(work.analysis?.tags||[]).map(item=>item.tag)].join(' ')).includes(query));items.sort((a,b)=>archiveSort==='rating'?(Number(b.rating)||0)-(Number(a.rating)||0):archiveSort==='bridge'?archiveBridgeScore(b)-archiveBridgeScore(a):archiveSort==='title'?String(a.title).localeCompare(String(b.title),'ko'):archiveSort==='saved'?String(b.savedAt||'').localeCompare(String(a.savedAt||'')):String(b.updatedAt||b.savedAt||'').localeCompare(String(a.updatedAt||a.savedAt||'')));$('#archiveResultCount').textContent=`${items.length}개 작품`;if(!items.length){box.innerHTML='<p class="library-empty">조건에 맞는 저장 작품이 없습니다.</p>';return}box.innerHTML=items.map(work=>{const poster=safeUrl(work.posterUrl),planned=(work.archiveState||'completed')==='planned',state=planned?'보고 싶음':'감상 완료',rating=planned?'미평가':`${'★'.repeat(Number(work.rating)||0)}${'☆'.repeat(5-(Number(work.rating)||0))}`,tags=(work.analysis?.tags||[]).slice(0,3).map(item=>`<span>#${esc(item.tag)}</span>`).join('');return`<article class="library-item"><button class="library-open" data-library-open="${esc(work.id)}">${poster?`<img src="${esc(poster)}" alt="${esc(work.title)} 표지" loading="lazy"/>`:'<span class="library-placeholder">✦</span>'}<span class="library-copy"><small>${esc(work.mediaType||work.type||'OTHER')} · ${esc(work.year||'연도 미상')}</small><strong>${esc(work.title)}</strong><em>${esc(work.creator||'작자 미상')}</em><span class="library-tags">${tags}</span></span></button><div class="library-meta"><span class="archive-state ${planned?'planned':''}">${state}</span><strong>${rating}</strong><small>Bridge ${archiveBridgeScore(work)}</small></div><div class="library-actions"><button data-library-edit="${esc(work.id)}">수정</button><button class="danger" data-library-delete="${esc(work.id)}">삭제</button></div></article>`}).join('')}
let archiveMetadataRepairJob=null;
async function repairArchiveMetadata(){if(archiveMetadataRepairJob)return archiveMetadataRepairJob;const pending=archive.filter(id=>{const work=works[id];return work&&!work.year&&!work._metadataResolved&&!work._metadataResolving});if(!pending.length)return;archiveMetadataRepairJob=(async()=>{let cursor=0;async function worker(){while(cursor<pending.length){const id=pending[cursor++],work=works[id];if(!work)continue;work._metadataResolving=true;try{const matched=await searchMetadata(work);works[id]=matched?{...work,...matched,id,title:work.title||matched.title,creator:work.creator&&work.creator!=='작자 미상'?work.creator:matched.creator,_metadataResolved:true,_metadataResolving:false}:{...work,_metadataResolved:true,_metadataResolving:false}}catch{works[id]={...work,_metadataResolved:true,_metadataResolving:false}}}}await Promise.all(Array.from({length:Math.min(3,pending.length)},worker));renderArchiveManagerBase();$$('#archiveLibrary small').forEach(element=>{element.textContent=element.textContent.replace('연도 미상','연도 확인 필요')});if(current&&pending.includes(current))renderWork()})().finally(()=>{archiveMetadataRepairJob=null});return archiveMetadataRepairJob}
const renderArchiveManagerBase=renderArchiveManager;
renderArchiveManager=function(){renderArchiveManagerBase();$$('#archiveLibrary small').forEach(element=>{element.textContent=element.textContent.replace('연도 미상','연도 확인 중')});repairArchiveMetadata()};
