async function updateArchiveItem(){const id=$('#editArchiveId').value,button=$('#updateArchiveBtn');button.disabled=true;button.textContent='Taste DNA 다시 계산 중…';try{const r=await fetch(`/api/archive/${encodeURIComponent(id)}`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({rating:Number($('#editArchiveRating').value),myComment:$('#editArchiveComment').value,archiveState:$('#editArchiveState').value})}),data=await r.json();if(!r.ok)throw new Error(data.error||'update');works[id]={...works[id],...data.work};await Promise.all([loadTasteProfile(),loadSimilarities(),loadConstellationGraph()]);$('#editArchiveDialog').close();renderArchive();paintBridgeWork();renderTasteReport();renderArchiveManager();if(current===id)renderWork();toast('아카이브와 Taste DNA를 수정했어요.')}catch(error){toast(error.message||'수정하지 못했습니다.')}finally{button.disabled=false;button.textContent='수정 내용 저장'}}
async function deleteArchiveItem(id){const work=works[id];if(!work||!confirm(`“${work.title}”을 내 성좌에서 삭제할까요?`))return;try{const r=await fetch(`/api/archive/${encodeURIComponent(id)}`,{method:'DELETE'}),data=await r.json();if(!r.ok)throw new Error(data.error||'delete');archive=archive.filter(item=>item!==id);$('#archiveCount').textContent=archive.length;await Promise.all([loadTasteProfile(),loadSimilarities(),loadConstellationGraph()]);renderArchive();paintBridgeWork();renderTasteReport();renderArchiveManager();if(current===id)renderWork();const t=$('#toast');clearTimeout(toastTimer);t.innerHTML='삭제했어요. <button id="undoArchiveDelete">실행 취소</button>';t.classList.add('show');$('#undoArchiveDelete').onclick=()=>restoreArchiveItem(work);toastTimer=setTimeout(()=>t.classList.remove('show'),6500)}catch(error){toast(error.message||'삭제하지 못했습니다.')}}
async function restoreArchiveItem(work){try{const r=await fetch('/api/archive',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({work,rating:work.rating||5,myComment:work.myComment||'',archiveState:work.archiveState||'completed'})}),data=await r.json();if(!r.ok)throw new Error(data.error||'restore');works[work.id]={...work,...data.work};archive=[work.id,...archive.filter(id=>id!==work.id)];$('#archiveCount').textContent=archive.length;await Promise.all([loadTasteProfile(),loadSimilarities(),loadConstellationGraph()]);renderArchive();paintBridgeWork();renderTasteReport();renderArchiveManager();if(current===work.id)renderWork();toast('작품을 다시 성좌에 복원했어요.')}catch(error){toast(error.message||'복원하지 못했습니다.')}}
