$('#searchInput').oninput=e=>{const q=e.target.value.trim();clearTimeout(searchTimer);if(searchController)searchController.abort();if(q.length<2){setSearchOpen(false);return}setSearchOpen(true);$('#searchResults').innerHTML='<div class="search-message">영화·책·애니를 함께 찾고 있어요…</div>';$('#sourceStatus').className='source-status loading';searchTimer=setTimeout(async()=>{searchController=new AbortController();try{const r=await fetch(`/api/search?q=${encodeURIComponent(q)}`,{signal:searchController.signal});if(!r.ok)throw new Error('search');const data=await r.json();data.items.forEach(w=>works[w.id]={...w,...works[w.id]});$('#searchResults').innerHTML=data.items.map(w=>{const poster=safeUrl(w.posterUrl);return`<button class="search-result" role="option" data-result="${esc(w.id)}"><span class="result-thumb" ${poster?`style="background-image:url('${esc(poster)}')"`:''}></span><span><strong>${esc(w.title)}<em class="provider-pill">${esc(w.source)}</em></strong><small>${esc(w.mediaType)} · ${esc(w.year||'연도 미상')} · ${esc(w.creator)}</small></span></button>`}).join('')||'<div class="search-message">검색 결과가 없습니다. 다른 제목으로 찾아보세요.</div>';const active=Object.entries(data.sources).filter(([,v])=>v==='ok').map(([k])=>k),waiting=Object.entries(data.sources).filter(([,v])=>v==='needs_key').map(([k])=>k);$('#sourceStatus').className='source-status '+(waiting.length?'partial':'');$('#sourceStatus').innerHTML=`<span class="live-dot"></span> ${esc(active.join(' · '))} 실시간 연결${waiting.length?` · ${esc(waiting.join(' · '))} 키 등록 대기`:''}`;}catch(err){if(err.name==='AbortError')return;$('#searchResults').innerHTML='<div class="search-message">검색 서비스에 잠시 연결할 수 없습니다. 다시 시도해 주세요.</div>';$('#sourceStatus').className='source-status partial';}},350)};
